import React, { useState } from 'react';
import { login } from './authService';

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(null);

  async function handleSubmit(e) {
    e.preventDefault();
    setError(null);
    try {
      await login(email, password);
      window.location.href = '/dashboard';
    } catch (err) {
      setError('Login failed. Please try again.');
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <h2>Login</h2>
      {error && <p className="error">{error}</p>}
      <input value={email} onChange={e => setEmail(e.target.value)} placeholder="Email" />
      <input type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="Password" />
      <button type="submit">Login</button>
    </form>
  );
}

import { getToken, isTokenExpired, refreshToken, saveToken } from './tokenManager';
import { fetchUser } from '../api/userApi';

export async function login(email, password) {
  const res = await fetch('/api/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password }),
  });
  if (!res.ok) throw new Error('Login failed');
  const data = await res.json();
  saveToken(data.token, data.expiresIn);
  return data;
}

export async function getCurrentUser() {
  const token = getToken();
  // BUG: sends the token without checking expiry first,
  // so an expired token makes the API return 401 and the page goes blank.
  return fetchUser(token);
}

export function logout() {
  saveToken(null, 0);
  window.location.href = '/login';
}

let token = null;
let expiresAt = 0;

export function saveToken(newToken, expiresInSeconds) {
  token = newToken;
  expiresAt = Date.now() + expiresInSeconds * 1000;
}

export function getToken() {
  return token;
}

export function isTokenExpired() {
  // BUG: always returns false, so the app never refreshes
  // an expired token and every API call fails with 401.
  return false;
}

export async function refreshToken() {
  const res = await fetch('/api/refresh', {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}` },
  });
  const data = await res.json();
  saveToken(data.token, data.expiresIn);
  return data.token;
}

export async function fetchUser(token) {
  const res = await fetch('/api/me', {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error('Failed to load user');
  return res.json();
}

export async function updateProfile(token, profile) {
  const res = await fetch('/api/me', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
    body: JSON.stringify(profile),
  });
  return res.json();
}

import React from 'react';
import { logout } from '../auth/authService';

export default function Header({ user }) {
  return (
    <header>
      <h1>ShopKart</h1>
      {user
        ? <button onClick={logout}>Logout ({user.name})</button>
        : <a href="/login">Login</a>}
    </header>
  );
}

export function formatPrice(amount) {
  return 'Rs. ' + Number(amount).toFixed(2);
}

export function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-IN');
}

import { login } from '../src/auth/authService';

test('login saves the token on success', async () => {
  global.fetch = jest.fn(() =>
    Promise.resolve({ ok: true, json: () => Promise.resolve({ token: 'abc', expiresIn: 3600 }) })
  );
  const data = await login('a@b.com', 'secret');
  expect(data.token).toBe('abc');
});

import { saveToken, isTokenExpired } from '../src/auth/tokenManager';

test('fresh token is not expired', () => {
  saveToken('abc', 3600);
  expect(isTokenExpired()).toBe(false);
});
